import periodictable as pt, json
AR="""هيدروجين هيليوم ليثيوم بيريليوم بورون كربون نيتروجين أكسجين فلور نيون صوديوم مغنيسيوم ألومنيوم سيليكون فوسفور كبريت كلور أرغون بوتاسيوم كالسيوم سكانديوم تيتانيوم فاناديوم كروم منغنيز حديد كوبالت نيكل نحاس خارصين غاليوم جرمانيوم زرنيخ سيلينيوم بروم كريبتون روبيديوم سترونشيوم إتريوم زركونيوم نيوبيوم موليبدنوم تكنيشيوم روثينيوم روديوم بلاديوم فضة كادميوم إنديوم قصدير أنتيمون تيلوريوم يود زينون سيزيوم باريوم لانثانوم سيريوم براسيوديميوم نيوديميوم بروميثيوم ساماريوم يوروبيوم غادولينيوم تيربيوم ديسبروسيوم هولميوم إربيوم ثوليوم إتربيوم لوتيتيوم هافنيوم تانتالوم تنغستن رينيوم أوزميوم إيريديوم بلاتين ذهب زئبق ثاليوم رصاص بزموت بولونيوم أستاتين رادون فرانسيوم راديوم أكتينيوم ثوريوم بروتكتينيوم يورانيوم نبتونيوم بلوتونيوم أمريسيوم كوريوم بركيليوم كاليفورنيوم أينشتاينيوم فيرميوم مندليفيوم نوبليوم لورنسيوم رذرفورديوم دوبنيوم سيبورغيوم بوريوم هاسيوم مايتنريوم دارمشتاتيوم رونتجينيوم كوبرنيسيوم نيهونيوم فليروفيوم موسكوفيوم ليفرموريوم تينيسين أوغانيسون""".split()
assert len(AR)==118,len(AR)
def pos(z):
    if z<=2: return (1,1 if z==1 else 18)
    if z<=10: p,s=2,3
    elif z<=18: p,s=3,11
    elif z<=36: return (4,z-18)
    elif z<=54: return (5,z-36)
    elif 57<=z<=71: return ('la',z-57+3)
    elif 89<=z<=103: return ('ac',z-89+3)
    elif z<=86:
        p=6; 
        if z<=56: return (6,z-54)
        return (6,z-86+18)
    else:
        if z<=88: return (7,z-86)
        return (7,z-118+18)
    i=z-s
    return (p,[1,2,13,14,15,16,17,18][i])
def cat(z):
    if z in (3,11,19,37,55,87): return 'alkali'
    if z in (4,12,20,38,56,88): return 'alkaline'
    if 57<=z<=71: return 'lanth'
    if 89<=z<=103: return 'act'
    if 21<=z<=30 or 39<=z<=48 or 72<=z<=80 or 104<=z<=112: return 'trans'
    if z in (5,14,32,33,51,52): return 'metalloid'
    if z in (9,17,35,53,85,117): return 'halogen'
    if z in (2,10,18,36,54,86,118): return 'noble'
    if z in (1,6,7,8,15,16,34): return 'nonmetal'
    return 'post'
STATE={z:'gas' for z in (1,2,7,8,9,10,17,18,36,54,86)}; STATE.update({35:'liquid',80:'liquid'})
FACT={1:"أخفّ العناصر وأكثرها انتشارًا في الكون، ويدخل في تركيب الماء.",2:"غاز خفيف لا يتفاعل، تُملأ به البالونات الطائرة.",3:"يُستعمل في بطاريات الجوالات والسيارات الكهربائية.",6:"أساس مركّبات الكائنات الحية، ومن صوره الألماس والجرافيت.",7:"يشكّل نحو 78% من الهواء.",8:"يشكّل نحو 21% من الهواء، وتحتاجه الكائنات الحية في التنفّس.",9:"يُضاف مركّب منه (الفلوريد) إلى معاجين الأسنان لحمايتها من التسوّس.",10:"يُستعمل في لافتات الإضاءة الحمراء البرّاقة.",11:"فلز ليّن يتفاعل بشدّة مع الماء، ويكوّن مع الكلور ملح الطعام.",12:"يحترق بلهب أبيض ساطع، ويدخل في تركيب الكلوروفيل في النباتات.",13:"فلز خفيف يقاوم التآكل، تُصنع منه العلب وأجزاء الطائرات.",14:"ثاني أكثر العناصر وفرة في القشرة الأرضية، ويُستعمل في رقائق الحواسيب.",15:"يوجد في العظام والأسنان، ويدخل في صناعة الأسمدة وأعواد الثقاب.",16:"مادة صلبة صفراء، تدخل في صناعة حمض الكبريتيك.",17:"غاز سامّ أصفر مخضرّ، تُستعمل مركّباته في تعقيم مياه الشرب والمسابح.",18:"أكثر الغازات النبيلة وفرة في الهواء، ويُملأ به بعض المصابيح.",19:"ضروري لعمل العضلات والأعصاب، ويوجد في الموز.",20:"يقوّي العظام والأسنان، ويوجد في الحليب ومنتجاته.",22:"فلز قوي وخفيف، يُستعمل في الطائرات والمفاصل الصناعية.",26:"أكثر الفلزات استعمالًا، يُصنع منه الفولاذ، ويوجد في هيموجلوبين الدم.",28:"يدخل في صناعة الفولاذ المقاوم للصدأ وبعض العملات المعدنية.",29:"موصل جيد جدًّا للكهرباء، تُصنع منه الأسلاك الكهربائية.",30:"يُغلَّف به الحديد لحمايته من الصدأ، وتُسمّى هذه العملية الجلفنة.",31:"ينصهر عند نحو 30 °س، أي يمكن أن يذوب في راحة اليد.",35:"أحد عنصرين فقط يكونان سائلين في درجة حرارة الغرفة.",47:"أفضل العناصر توصيلًا للكهرباء، تُصنع منه الحلي.",50:"يُطلى به الحديد في صناعة العلب، ويدخل في سبيكة البرونز.",53:"ضروري لعمل الغدة الدرقية، ولذلك يُضاف إلى ملح الطعام.",74:"أعلى الفلزات درجة انصهار، واستُعمل في فتائل المصابيح.",78:"فلز ثمين يُستعمل في المحوّلات الحفّازة في السيارات.",79:"فلز لا يصدأ، تُصنع منه الحلي والعملات.",80:"الفلز الوحيد السائل في درجة حرارة الغرفة، وهو سامّ.",82:"فلز ثقيل سامّ، استُعمل قديمًا في الأنابيب والدهانات.",86:"غاز نبيل مشعّ يتسرّب طبيعيًّا من بعض الصخور.",92:"عنصر مشعّ يُستعمل وقودًا في محطات الطاقة النووية."}
out=[]
for e in pt.elements:
    if e.number==0: continue
    z=e.number; p,g=pos(z)
    m=e.mass
    out.append({"z":z,"s":e.symbol,"en":e.name.capitalize(),"ar":AR[z-1],"m":round(m,3) if z<=94 else round(m),"p":p,"g":g,"c":cat(z),
                "st":STATE.get(z,'solid' if z<=103 else 'unknown'),"r":1 if (z>=84 or z in (43,61)) else 0,"f":FACT.get(z,"")})
# checks
chk={1:(1,1),2:(1,18),5:(2,13),10:(2,18),11:(3,1),18:(3,18),19:(4,1),26:(4,8),30:(4,12),31:(4,13),36:(4,18),47:(5,11),54:(5,18),55:(6,1),56:(6,2),57:('la',3),71:('la',17),72:(6,4),79:(6,11),80:(6,12),86:(6,18),87:(7,1),89:('ac',3),103:('ac',17),104:(7,4),118:(7,18)}
for z,(p,g) in chk.items():
    o=out[z-1]; assert (o['p'],o['g'])==(p,g),(z,o['p'],o['g'])
seen=set()
for o in out:
    k=(o['p'],o['g']); assert k not in seen,k; seen.add(k)
assert [o['s'] for o in out][:10]==['H','He','Li','Be','B','C','N','O','F','Ne']
json.dump(out,open('elements.json','w'),ensure_ascii=False,separators=(',',':'))
from collections import Counter; print(Counter(o['c'] for o in out)); print(len(out), sum(1 for o in out if o['f']))
